\section{Introduction}

\subsection{Motivation}
A classifier partitions its input space into regions of differing predicted
labels; the interface between them---the \emph{decision surface}---encodes what
the classifier has learned. For networks built from rectified linear units,
$\sigma(t)=\max(0,t)$, this surface is rigidly combinatorial: the input space
$\mathbb{R}^n$ is subdivided into finitely many convex polyhedral
\emph{activation regions}, on each of which every neuron is identically active or
inactive and $f$ reduces to an affine function. The zero set $V(f)$ meets each
region in a flat piece of an affine hyperplane, and these pieces glue into a
global piecewise-linear hypersurface.

\subsection{The Hodge analogy}
The Hodge conjecture asserts that on a smooth complex projective variety every
rational $(p,p)$-cohomology class is a rational combination of classes of
algebraic subvarieties; it is open in general. For a ReLU decision surface the
analogue is immediate: each cellular piece of $V(f)$ lies in an affine hyperplane
$\{a\cdot x=b\}$, the zero locus of a degree-one polynomial, hence an algebraic
cycle. The surface is \emph{built} from algebraic cycles, so any homology class
it carries is a combination of them. The interesting question is thus magnitude,
not existence.

\subsection{Contributions}
(1) An exact Betti--rank identity (Theorem~\ref{thm:brf}). (2) Its subtraction
form and consequences (Theorem~\ref{thm:sub}, Corollaries~\ref{cor:van},
\ref{cor:conv}). (3) A width calculus for $P(w)=\prod_i 2^{w_i}$
(Theorems~\ref{thm:closed}--\ref{thm:mult}). (4) A monotone width bound
(Theorem~\ref{thm:wb}).

\section{Preliminaries: cellular homology}

Fix a field $F$. We model the cellular chain data of the decision surface as three
finite-dimensional $F$-vector spaces with linear boundary maps,
\[
C_2 \xrightarrow{\;d_2\;} C_1 \xrightarrow{\;d_1\;} C_0,
\]
where $C_1$ is spanned by the middle-dimensional cells (one basis vector per flat
facet) and $d_1, d_2$ are incidence maps.

\begin{definition}[Cycles]
The cycles in degree one are $Z := \ker d_1 \subseteq C_1$.
\end{definition}

\begin{definition}[Boundaries]
The boundaries are $\rangeop d_2 \subseteq C_1$. When $d_1\circ d_2 = 0$ they lie
inside $Z$, and we regard them as a submodule $B \subseteq Z$, the pullback of
$\rangeop d_2$ along $Z \hookrightarrow C_1$.
\end{definition}

\begin{definition}[Homology]
The degree-one homology is $H := Z/B = \ker d_1 / \rangeop d_2$; its dimension
$\dim H$ is the middle Betti number.
\end{definition}

\begin{lemma}[Boundaries are cycles]\label{lem:bc}
If $d_1\circ d_2 = 0$ then $\rangeop d_2 \le \ker d_1$.
\end{lemma}
\begin{proof}
$d_1\circ d_2 = 0$ says every vector in the image of $d_2$ is annihilated by
$d_1$, i.e. lies in $\ker d_1$.
\end{proof}

\begin{lemma}[Betti bounded by cells]\label{lem:cellbound}
$\dim H \le \dim C_1$.
\end{lemma}
\begin{proof}
$\dim(Z/B)\le \dim Z \le \dim C_1$: a quotient does not increase dimension, and a
submodule does not exceed its ambient space.
\end{proof}

\begin{lemma}[Euler identity]\label{lem:euler}
$\dim H + \dim B = \dim Z$.
\end{lemma}
\begin{proof}
The dimension law for a quotient: $\dim(Z/B)+\dim B = \dim Z$.
\end{proof}

\section{The exact Betti--rank identity}

Throughout, $C_2, C_1, C_0$ are finite-dimensional and $d_1\circ d_2 = 0$.

\begin{lemma}[Boundary dimension equals $d_2$-rank]\label{lem:bd}
$\dim B = \rank d_2$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:bc}, $\rangeop d_2 \le Z$. When $S \le T$, the pullback of $S$
along $T \hookrightarrow C_1$ is isomorphic to $S$. With $S=\rangeop d_2$ and
$T=Z$ this gives $B \cong \rangeop d_2$, so $\dim B = \rank d_2$.
\end{proof}

\begin{lemma}[Rank--nullity for $d_1$]\label{lem:rn}
$\rank d_1 + \dim Z = \dim C_1$, where $Z=\ker d_1$.
\end{lemma}
\begin{proof}
Rank--nullity for $d_1 : C_1 \to C_0$.
\end{proof}

\begin{theorem}[Exact Betti--rank formula]\label{thm:brf}
For a three-term chain complex over a field with $d_1\circ d_2 = 0$,
\[
\dim H + \rank d_1 + \rank d_2 = \dim C_1.
\]
\end{theorem}
\begin{proof}
From Lemma~\ref{lem:euler}, $\dim H + \dim B = \dim Z$. Substitute
$\dim B = \rank d_2$ (Lemma~\ref{lem:bd}) and $\dim Z = \dim C_1 - \rank d_1$
(Lemma~\ref{lem:rn}) to get $\dim H + \rank d_2 = \dim C_1 - \rank d_1$, which
rearranges to the claim.
\end{proof}

\begin{theorem}[Subtraction form]\label{thm:sub}
$\dim H = \dim C_1 - \rank d_1 - \rank d_2$.
\end{theorem}
\begin{proof}
Transpose the rank terms in Theorem~\ref{thm:brf}; the subtraction is
well-defined since $\rank d_1 + \rank d_2 \le \dim C_1$.
\end{proof}

\begin{remark}
Homology is exactly the part of $C_1$ that \emph{neither} differential sees:
$d_1$ accounts for the $\rank d_1$ non-cycle directions, and $d_2$ for the
$\rank d_2$ cycle-directions that are boundaries. The classical inequality
$\dim H \le \dim C_1$ is its shadow.
\end{remark}

\begin{corollary}[Vanishing]\label{cor:van}
If $\dim C_1 = 0$ then $\dim H = 0$.
\end{corollary}
\begin{proof}
$0 \le \dim H \le \dim C_1 = 0$ by Lemma~\ref{lem:cellbound}.
\end{proof}

\begin{corollary}[Converse]\label{cor:conv}
If $\dim H > 0$ then $\dim C_1 > 0$.
\end{corollary}
\begin{proof}
Contrapositive of Corollary~\ref{cor:van}, or $0 < \dim H \le \dim C_1$ directly.
\end{proof}

\section{The activation-pattern (width) calculus}

Consider a network with $L$ hidden layers of widths $w=(w_1,\dots,w_L)$,
$w_i\in\mathbb{N}$.

\begin{definition}[Activation pattern]
An activation pattern is a choice of Boolean state for each hidden neuron:
$\mathrm{AP}(L,w) := \prod_{i=1}^L \{0,1\}^{w_i}$. Each pattern selects at most one
flat facet of the decision surface.
\end{definition}

\begin{theorem}[Closed form]\label{thm:closed}
$\bigl|\mathrm{AP}(L,w)\bigr| = \prod_{i=1}^L 2^{w_i} = 2^{\sum_i w_i}$.
\end{theorem}
\begin{proof}
A product set has cardinality the product of cardinalities,
$|\{0,1\}^{w_i}|=2^{w_i}$; collect exponents.
\end{proof}

We write $P(w):=\prod_i 2^{w_i}$.

\begin{theorem}[Monotonicity]\label{thm:mono}
If $w_i \le w_i'$ for all $i$, then $P(w)\le P(w')$.
\end{theorem}
\begin{proof}
Each factor satisfies $2^{w_i}\le 2^{w_i'}$ since $t\mapsto 2^t$ is
non-decreasing; a product of termwise inequalities between non-negatives is
preserved.
\end{proof}

\begin{theorem}[Multiplicativity under parallel composition]\label{thm:mult}
For profiles $w=(w_1,\dots,w_L)$ and $v=(v_1,\dots,v_M)$ with concatenation
$w\,\Vert\,v$,
\[
\bigl|\mathrm{AP}(L+M,\,w\,\Vert\,v)\bigr|
 = \bigl|\mathrm{AP}(L,w)\bigr|\cdot\bigl|\mathrm{AP}(M,v)\bigr|,
\]
i.e. $P(w\,\Vert\,v)=P(w)\,P(v)$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:closed} each side is a power of $2$ with exponent
$\sum_i w_i + \sum_j v_j$; the law of exponents splits it as
$2^{\sum w}\,2^{\sum v}$.
\end{proof}

\section{Synthesis: the monotone width bound}

The bridge hypothesis is that the chain group has at most one basis cell per
activation region, so $\dim C_1 \le P(w)$ for the network's own profile $w$.

\begin{theorem}[Monotone width bound]\label{thm:wb}
If $\dim C_1 \le P(w)$ and $w_i \le w_i'$ for all $i$, then
\[
\dim H \;\le\; P(w') \;=\; \prod_i 2^{w_i'}.
\]
\end{theorem}
\begin{proof}
Chain the inequalities
$\dim H \le \dim C_1 \le P(w) \le P(w')$, using Lemma~\ref{lem:cellbound}, the
hypothesis, and Theorem~\ref{thm:mono}.
\end{proof}

\begin{remark}
The bound is architectural (independent of learned weights and data) and uniform
downward (monotonicity makes a wide-profile bound cover every narrower one). Its
exponential form $2^{\sum_i w_i}$ reflects the genuine combinatorial explosion of
activation regions.
\end{remark}

\section{Discussion and future directions}

\begin{conjecture}[Bigraded refinement]
For input-adjacent width $w_1$ and output-adjacent width $w_L$, each mixed Betti
number should satisfy
$h^{p,q} \le \binom{w_1}{p}\binom{w_L}{q}\prod_i w_i$, refining the single
exponential bound into a bigraded pyramid. The first layer controls how cells are
cut, the last how they are glued, so homology should split along a bidegree
reading input and output widths separately.
\end{conjecture}

\begin{conjecture}[Sharpness]
The bound $\dim H \le \prod_i 2^{w_i}$ is asymptotically tight: for every profile
there is a network realizing a Betti number that is a fixed positive fraction of
the bound. Generic hyperplane arrangements realize a constant fraction of all
sign-cells, and a surface can be engineered so a constant fraction carry
independent homology classes.
\end{conjecture}

\begin{conjecture}[Subadditivity under composition]
If a deep network factors as a composition of two sub-networks, the Betti numbers
of its decision surface are bounded by a convolution of those of the parts:
composition of piecewise-linear maps refines activation regions, and refinement
can merge classes but cannot manufacture unaccounted-for ones.
\end{conjecture}

\section{Conclusion}
On ReLU decision surfaces the Hodge-type question is affirmative by construction,
so we pass to exact magnitude. The Betti number obeys
$\dim H = \dim C_1 - \rank d_1 - \rank d_2$; the cell count obeys the monotone,
multiplicative calculus $P(w)=\prod_i 2^{w_i}$; together they give the
architectural ceiling $\dim H \le \prod_i 2^{w_i}$.

